'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './orbit-border.css'

export type OrbitBorderProps = React.ComponentPropsWithoutRef<'div'> & {
    /** Colour of the light travelling around the edge. */
    color?: string
    /** Seconds per lap. */
    duration?: number
    /** Border width in px. */
    width?: number
    /** Corner radius in px. */
    radius?: number
    paused?: boolean
}

const OrbitBorder = ({ color = '#38bdf8', duration = 4, width = 1.5, radius = 14, paused = false, className, style, children, ...props }: OrbitBorderProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-orbit', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{
            '--rad-fx-orbit-color': color,
            '--rad-fx-orbit-duration': `${duration}s`,
            '--rad-fx-orbit-width': `${width}px`,
            '--rad-fx-orbit-radius': `${radius}px`,
            ...style
        } as React.CSSProperties}
        {...props}
    >
        {children}
    </div>
}

export default OrbitBorder

/* OrbitBorder: a comet of light running around the element's edge. The animated
   angle needs @property; browsers without it show a still highlight instead. */
@property --rad-fx-orbit-angle {
    syntax: '<angle>';
    inherits: false;
    initial-value: 0deg;
}

.rad-fx-orbit {
    position: relative;
    border-radius: var(--rad-fx-orbit-radius, 14px);
}

.rad-fx-orbit::before {
    content: '';
    position: absolute;
    inset: 0;
    padding: var(--rad-fx-orbit-width, 1.5px);
    border-radius: inherit;
    pointer-events: none;
    background: conic-gradient(
        from var(--rad-fx-orbit-angle),
        transparent 0deg,
        transparent 280deg,
        var(--rad-fx-orbit-color) 340deg,
        transparent 360deg
    );
    /* Show the gradient only in the padding ring, not behind the content. */
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: rad-fx-orbit var(--rad-fx-orbit-duration, 4s) linear infinite;
}

.rad-fx-orbit[data-state='paused']::before { animation-play-state: paused; }

@keyframes rad-fx-orbit {
    to { --rad-fx-orbit-angle: 360deg; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-orbit::before { animation: none; --rad-fx-orbit-angle: 45deg; }
}

[data-rad-fx-motion='reduce'] .rad-fx-orbit::before { animation: none; --rad-fx-orbit-angle: 45deg; }
